var i=`0750-canjeero`;var t=`world-0750`;var a=`SO`;var o=`eastern-africa`;var r=8;var s=397;var l={en:`Canjeero`,ua:`Канджеро`};var u={en:`Canjeero is a Somalia classic prepared with all-purpose flour, sorghum flour, instant yeast. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Канджеро, страва кухні країни Сомалі зі складниками: пшеничне борошно універсальне, соргове борошно, інстантні дріжджі. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`all-purpose-flour`,200,`g`],[`sorghum-flour`,250,`g`],[`water`,630,`ml`],[`instant-yeast`,4,`g`],[`white-granulated-sugar`,15,`g`]]},{en:`Cover the batter loosely and leave in a suitable warm, clean place for about 360 minutes to become bubbly and lightly tangy; do not refrigerate during active fermentation.`,ua:`Нещільно накрийте тісто й залиште приблизно на 360 хвилин у чистому теплому місці до появи бульбашок і легкої кислинки; під час активного бродіння не ставте в холодильник.`,t:[`sourdough-fermentation`],m:360,i:[]},{en:`Cook canjeero in thin rounds over medium heat, mostly from one side, until bubbles open and the surface dries.`,ua:`Смажте канджеро тонкими круглими коржами на помірному вогні переважно з одного боку до появи бульбашок і сухої поверхні.`,t:[`griddle-cooking`],m:24,i:[[`sunflower-oil`,20,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`honey`,75,`g`]]}];var d={slug:i,id:t,country:`SO`,region:o,servings:8,minutes:397,title:l,text:u,steps:g};export{a as country,d as default,t as id,s as minutes,o as region,r as servings,i as slug,g as steps,u as text,l as title};